// Package queue is a FIFO queue of strings.
package queue

// Queue holds strings in arrival order.
type Queue struct{ items []string }

// New returns an empty queue.
func New() *Queue { return &Queue{} }

// Len is the number of queued items.
func (q *Queue) Len() int { return len(q.items) }

// Push appends s.
func (q *Queue) Push(s string) { q.items = append(q.items, s) }

// Pop removes and returns the oldest item; false when the queue is empty.
func (q *Queue) Pop() (string, bool) {
	if len(q.items) == 0 {
		return "", false
	}
	s := q.items[0]
	q.items = q.items[1:]
	return s, true
}

package queue_test

import (
	"testing"

	"example.com/events/queue"
)

func TestNewIsEmpty(t *testing.T) {
	if n := queue.New().Len(); n != 0 {
		t.Fatalf("Len() = %d, want 0", n)
	}
}

func TestPushThenPop(t *testing.T) {
	q := queue.New()
	q.Push("a")
	if s, ok := q.Pop(); !ok || s != "a" {
		t.Fatalf("Pop() = %q, %v; want \"a\", true", s, ok)
	}
}
